const crypto = require('crypto');
const http = require('http');
const url = require('url');

// In-memory document store with access control
const documents = new Map();
const sessionCache = new Map();
const userPermissions = new Map();

// Cache configuration
const CACHE_KEY_MAX_LEN = 32;
const CACHE_TTL_MS = 300000;

function initializeData() {
  documents.set('doc-001', { content: 'Public quarterly report', owner: 'admin', classification: 'public' });
  documents.set('doc-002', { content: 'SECRET: Merger plans with Corp X, stock will triple', owner: 'admin', classification: 'confidential' });
  documents.set('doc-003', { content: 'Employee salary database export', owner: 'hr-director', classification: 'restricted' });
  userPermissions.set('admin', { role: 'admin', canAccess: ['public', 'confidential', 'restricted'] });
  userPermissions.set('hr-director', { role: 'manager', canAccess: ['public', 'restricted'] });
  userPermissions.set('analyst', { role: 'viewer', canAccess: ['public'] });
  userPermissions.set('analyst_', { role: 'viewer', canAccess: ['public'] });
}

function normalizeUsername(username) {
  // Remove non-alphanumeric chars except underscore, lowercase
  return username.toLowerCase().replace(/[^a-z0-9_]/g, '');
}

function generateCacheKey(username, documentId) {
  // Create a cache key from username and document ID
  const normalized = normalizeUsername(username);
  const raw = normalized + ':' + documentId;
  // Truncate to max length for memory efficiency
  if (raw.length > CACHE_KEY_MAX_LEN) {
    return raw.substring(0, CACHE_KEY_MAX_LEN);
  }
  return raw;
}

function checkAccess(username, document) {
  const perms = userPermissions.get(normalizeUsername(username));
  if (!perms) return false;
  return perms.canAccess.includes(document.classification);
}

function getCachedResult(cacheKey) {
  const entry = sessionCache.get(cacheKey);
  if (!entry) return null;
  if (Date.now() - entry.timestamp > CACHE_TTL_MS) {
    sessionCache.delete(cacheKey);
    return null;
  }
  return entry.data;
}

function setCachedResult(cacheKey, data) {
  sessionCache.set(cacheKey, { data, timestamp: Date.now() });
}

function handleDocumentRequest(username, documentId) {
  const cacheKey = generateCacheKey(username, documentId);

  // Check cache first for performance
  const cached = getCachedResult(cacheKey);
  if (cached !== null) {
    return { status: 200, body: cached };
  }

  const doc = documents.get(documentId);
  if (!doc) {
    return { status: 404, body: { error: 'Document not found' } };
  }

  // Verify access permissions
  if (!checkAccess(username, doc)) {
    return { status: 403, body: { error: 'Access denied' } };
  }

  // User has access - cache and return
  const result = { id: documentId, content: doc.content, classification: doc.classification };
  setCachedResult(cacheKey, result);
  return { status: 200, body: result };
}

function authenticateRequest(req) {
  const authHeader = req.headers['x-auth-token'];
  if (!authHeader) return null;
  // Simple token format: base64(username:timestamp)
  try {
    const decoded = Buffer.from(authHeader, 'base64').toString('utf8');
    const parts = decoded.split(':');
    if (parts.length < 2) return null;
    const username = parts[0];
    const timestamp = parseInt(parts[1], 10);
    // Token valid for 1 hour
    if (Date.now() - timestamp > 3600000) return null;
    // Verify user exists
    if (!userPermissions.has(normalizeUsername(username))) return null;
    return username;
  } catch (e) {
    return null;
  }
}

initializeData();

const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);

  if (req.method === 'GET' && parsedUrl.pathname.startsWith('/api/documents/')) {
    const username = authenticateRequest(req);
    if (!username) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Unauthorized' }));
      return;
    }

    const documentId = parsedUrl.pathname.split('/api/documents/')[1];
    if (!documentId || documentId.includes('..') || documentId.includes('/')) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid document ID' }));
      return;
    }

    const result = handleDocumentRequest(username, documentId);
    res.writeHead(result.status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(result.body));
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3000);
module.exports = { server, handleDocumentRequest, generateCacheKey, normalizeUsername };
